<template>
  <div class="ops-page" v-loading="loading">
    <header class="ops-header"><div><p class="eyebrow">卜叽岛 / 内容运营</p><h1>让每个角色鲜活起来</h1><p class="muted">{{published ? '正式内容已发布' : '尚未发布正式内容'}} · 草稿版本 {{version}} <span v-if="dirty"> · 有未保存修改</span></p></div><div class="actions"><el-button @click="refresh" :disabled="busy">刷新</el-button><el-button @click="preview" :disabled="dirty||!can('content:preview')">预览</el-button><el-button @click="save" :loading="busy" :disabled="!can('content:edit')">保存草稿</el-button><el-button type="primary" @click="publish" :disabled="dirty||busy||!can('content:publish')">发布</el-button></div></header>
    <el-alert v-if="error" :title="error" type="error" show-icon :closable="false" class="notice" />
    <div class="overview"><div v-for="g in groups.slice(0,5)" :key="g.key"><b>{{doc[g.key]?.length||0}}</b><span>{{g.label}}</span></div><div><b>{{assets.length}}</b><span>素材</span></div></div>
    <el-tabs v-model="tab" @tab-change="selected=null">
      <el-tab-pane v-for="g in groups" :key="g.key" :label="g.label" :name="g.key" />
      <el-tab-pane label="素材库" name="assets"/><el-tab-pane label="实体关联" name="entities"/><el-tab-pane label="发布历史" name="history"/><el-tab-pane v-if="can('content:audit')" label="操作记录" name="audit"/>
    </el-tabs>
    <section v-if="isContent" class="editor-grid">
      <aside class="item-list"><div class="list-heading"><b>{{group.label}}</b><el-button @click="add" size="small" :disabled="!can('content:edit')">新增</el-button></div>
        <el-input v-model="search" placeholder="搜索名称" clearable />
        <button v-for="item in filtered" :key="item.id" class="item" :class="{selected:selected===item}" @click="selected=item"><strong>{{item.name||pageName(item.id)||'未命名'}}</strong><small>{{item.id}}</small><span v-if="item.available===false">已下架 · 保留已有权益</span></button>
        <el-empty v-if="!filtered.length" description="从新增第一项内容开始" :image-size="70" />
      </aside>
      <article v-if="selected" class="edit-card">
        <div class="list-heading"><h2>{{selected.name||pageName(selected.id)||'编辑内容'}}</h2><span class="muted">{{selected.id}}</span><el-button v-if="tab==='products'||tab==='pages'" type="danger" text @click="removeSelected" :disabled="!can('content:edit')">从草稿移除</el-button></div>
        <el-form label-position="top" :disabled="!can('content:edit')" @input="dirty=true" @change="dirty=true">
          <el-form-item v-if="tab!=='pages'" label="名称"><el-input v-model="selected.name" maxlength="60"/></el-form-item>
          <template v-if="tab==='characters'">
            <el-form-item label="角色编码（发布后固定）"><el-input v-model="selected.code" maxlength="32"/></el-form-item>
            <el-form-item label="角色介绍"><el-input v-model="selected.description" type="textarea" maxlength="500"/></el-form-item>
            <el-form-item label="默认免费造型"><el-select v-model="selected.defaultAppearanceId"><el-option v-for="a in doc.appearances.filter(a=>a.characterId===selected.id)" :key="a.id" :label="a.name" :value="a.id"/></el-select></el-form-item>
            <el-form-item label="小窝背景（不选则使用公共默认背景）"><asset-select v-model="selected.backgroundAssetId" :assets="assets" @change="dirty=true"/></el-form-item>
            <el-form-item label="允许新领养"><el-switch v-model="selected.adoptionEnabled"/></el-form-item>
          </template>
          <template v-if="tab==='appearances'">
            <el-form-item label="所属角色"><el-select v-model="selected.characterId"><el-option v-for="c in doc.characters" :key="c.id" :label="c.name" :value="c.id"/></el-select></el-form-item>
            <div class="two-col"><el-form-item label="兑换叽分（0 表示免费领取）"><el-input-number v-model="selected.price" :min="0" :max="1000000" :precision="0"/></el-form-item><el-form-item label="开放获取"><el-switch v-model="selected.available"/></el-form-item></div>
            <h3>表情素材</h3><p class="muted">必需状态均需配置。静态素材保持同一套造型；动画可以稍后补充。</p>
            <div class="two-col"><el-form-item v-for="[key,label] in slots" :key="key" :label="label"><asset-select v-model="selected.slots[key]" :assets="assets" @change="dirty=true"/></el-form-item></div>
            <el-button @click="fillSlots">把正常图应用到所有空槽位</el-button>
            <h3>可选待机图集</h3><el-switch :model-value="!!selected.animation" @change="v=>{selected.animation=v?{assetId:'',columns:1,rows:1,frames:1,fps:12}:null;dirty=true}"/>
            <template v-if="selected.animation"><asset-select v-model="selected.animation.assetId" :assets="assets" @change="dirty=true"/><div class="two-col"><el-form-item v-for="key in ['columns','rows','frames','fps']" :key="key" :label="({columns:'列数',rows:'行数',frames:'帧数',fps:'每秒帧数'})[key]"><el-input-number v-model="selected.animation[key]" :min="1" :max="key==='fps'?30:512"/></el-form-item></div></template>
          </template>
          <template v-if="tab==='accessories'">
            <div class="two-col"><el-form-item label="穿戴部位"><el-select v-model="selected.slot"><el-option label="头部" value="head"/><el-option label="面部" value="face"/><el-option label="颈部" value="neck"/><el-option label="背部" value="back"/><el-option label="手持" value="hand"/></el-select></el-form-item><el-form-item label="兑换叽分（0 表示免费领取）"><el-input-number v-model="selected.price" :min="0" :max="1000000" :precision="0"/></el-form-item></div>
            <el-form-item label="开放获取"><el-switch v-model="selected.available"/></el-form-item><el-form-item label="饰品图片"><asset-select v-model="selected.assetId" :assets="assets" @change="dirty=true"/></el-form-item>
            <h3>适配与位置</h3><p class="muted">每条适配明确到造型。位置以画布千分比填写，发布后不能直接移除已有适配。</p>
            <div v-for="(fit,i) in selected.compatible" :key="i" class="fit"><el-select v-model="fit.appearanceId" @change="v=>{fit.characterId=doc.appearances.find(a=>a.id===v)?.characterId;dirty=true}"><el-option v-for="a in doc.appearances" :key="a.id" :label="roleName(a.characterId)+' / '+a.name" :value="a.id"/></el-select><div class="fit-numbers"><el-form-item v-for="key in ['x','y','width','height','layer']" :key="key" :label="({x:'左侧',y:'顶部',width:'宽度',height:'高度',layer:'层级'})[key]"><el-input-number v-model="fit[key]" :controls="false" :min="key==='layer'?-10:-1000" :max="key==='layer'?10:2000"/></el-form-item></div></div>
            <el-button @click="selected.compatible.push({characterId:'',appearanceId:'',x:0,y:0,width:300,height:300,layer:1});dirty=true">新增适配</el-button>
          </template>
          <template v-if="tab==='pages'">
            <el-form-item label="页面"><el-select v-model="selected.id"><el-option v-for="(name,id) in pageNames" :key="id" :label="name" :value="id"/></el-select></el-form-item>
            <el-form-item label="背景"><asset-select v-model="selected.backgroundAssetId" :assets="assets" @change="dirty=true"/></el-form-item><el-form-item label="已有 Banner 位置（按顺序）"><asset-select v-model="selected.banners" multiple :assets="assets" @change="dirty=true"/></el-form-item>
          </template>
          <template v-if="tab==='products'">
            <el-form-item label="商品价格（元）"><el-input-number v-model="selected.price" :precision="2" :min="0" :max="999999.99"/></el-form-item>
            <el-form-item label="封面"><asset-select v-model="selected.coverAssetId" :assets="assets" @change="dirty=true"/></el-form-item><el-form-item label="详情图片（按选择顺序展示）"><asset-select v-model="selected.detailAssetIds" multiple :assets="assets" @change="dirty=true"/></el-form-item>
          </template>
        </el-form>
      </article><el-empty v-else description="选择左侧内容开始编辑"/>
    </section>
    <section v-else-if="tab==='assets'" class="edit-card"><h2>素材库</h2><p class="muted">上传已优化的 PNG / JPEG，单文件不超过 10 MB；上传不会自动发布。</p><el-input v-model="license" placeholder="填写来源与使用授权说明"/><input type="file" accept="image/png,image/jpeg" :disabled="!can('content:edit')||busy" @change="upload"/><div class="asset-grid"><div v-for="a in assets" :key="a.id"><protected-image :asset-id="a.id"/><strong>{{a.original_name}}</strong><small>{{a.width}} × {{a.height}} · {{Math.ceil(a.size_bytes/1024)}} KB</small><el-button text @click="copy(a.id)">复制素材编号</el-button><el-button text @click="assetReferences(a)">查看引用</el-button><el-button text type="danger" :disabled="!can('content:edit')" @click="removeAsset(a)">移除未引用素材</el-button></div></div><el-button @click="moreAssets">加载更多</el-button></section>
    <section v-else-if="tab==='entities'" class="edit-card"><h2>实体与角色关联</h2><p class="muted">保持已发行编码、领养和进度。角色需先发布；已建立的角色关联不可直接改绑。</p><el-table :data="entities"><el-table-column prop="name" label="名称"/><el-table-column prop="id" label="实体编号"/><el-table-column prop="ip_code" label="已有 IP 编码"/><el-table-column label="角色"><template #default="{row}"><el-select v-model="row.character_id" :disabled="!!row.saved||!can('content:edit')"><el-option v-for="c in doc.characters" :key="c.id" :label="c.name" :value="c.id"/></el-select><el-button @click="mapEntity(row)" :disabled="!!row.saved||!can('content:edit')">关联</el-button></template></el-table-column></el-table><el-button @click="moreEntities">加载更多</el-button></section>
    <section v-else-if="tab==='history'" class="edit-card"><h2>发布历史</h2><el-table :data="history"><el-table-column prop="id" label="版本编号"/><el-table-column prop="created_at" label="发布时间"/><el-table-column label="操作"><template #default="{row}"><el-button @click="inspectRelease(row)">查看</el-button><el-button @click="rollback(row)" :disabled="busy||!can('content:publish')">回滚内容</el-button></template></el-table-column></el-table><el-button @click="moreHistory">加载更多</el-button></section>
    <section v-else class="edit-card"><h2>操作记录</h2><el-table :data="audits"><el-table-column prop="title" label="操作"/><el-table-column prop="oper_name" label="操作者"/><el-table-column prop="oper_param" label="对象"/><el-table-column prop="oper_time" label="时间"/></el-table><el-button @click="moreAudit">加载更多</el-button></section>
    <el-dialog v-model="previewOpen" title="草稿预览 · 不影响真实宠物" width="min(900px,95vw)"><template v-if="previewDoc"><div class="two-col"><el-select v-model="previewLook"><el-option v-for="a in previewDoc.appearances" :key="a.id" :label="a.name" :value="a.id"/></el-select><el-select v-model="previewExpression"><el-option v-for="[value,label] in slots" :key="value" :value="value" :label="label"/></el-select></div><el-select v-model="previewExtras" multiple placeholder="选择兼容饰品"><el-option v-for="a in compatibleExtras" :key="a.id" :value="a.id" :label="a.name"/></el-select><div class="preview-stage"><protected-image v-if="previewBackground" :asset-id="previewBackground" class="preview-bg"/><protected-image v-if="previewAppearance" :asset-id="previewAppearance.slots[previewExpression]" class="preview-bird"/><protected-image v-for="a in selectedExtras" :key="a.id" :asset-id="a.assetId" class="preview-extra" :style="accessoryStyle(a)"/></div><p v-if="previewToken">草稿预览凭据有效 15 分钟，仅用于受控的小程序预览入口。</p><el-button v-if="previewToken" @click="copy(previewToken)">复制小程序预览凭据</el-button><div v-for="page in previewDoc.pages" :key="page.id"><h3>{{pageName(page.id)}}</h3><protected-image v-if="page.backgroundAssetId" :asset-id="page.backgroundAssetId" class="page-thumb"/><protected-image v-for="a in page.banners" :key="a" :asset-id="a" class="page-thumb"/></div><h3>商品展示</h3><div class="asset-grid"><div v-for="p in previewDoc.products" :key="p.id"><protected-image :asset-id="p.coverAssetId"/><b>{{p.name}}</b><span>¥ {{p.price}}</span><protected-image v-for="a in p.detailAssetIds" :key="a" :asset-id="a"/></div></div></template></el-dialog>
  </div>
</template>
<script setup>
import { ElMessage, ElMessageBox } from 'element-plus'
import { api, id } from '@/api/operations'
import useUserStore from '@/store/modules/user'
import AssetSelect from './components/AssetSelect.vue'
import ProtectedImage from './components/ProtectedImage.vue'
const user=useUserStore();const can=p=>user.permissions.includes(p)
const groups=[{key:'characters',label:'角色 IP'},{key:'appearances',label:'整套造型'},{key:'accessories',label:'独立饰品'},{key:'pages',label:'背景与 Banner'},{key:'products',label:'商品'}]
const pageNames={nestDefault:'小窝默认',city:'城市',shop:'商城',profile:'我的'},pageName=id=>pageNames[id]
const slots=[['normal','正常'],['happy','开心'],['hungry','饥饿'],['thirsty','口渴'],['lonely','需要陪伴'],['shy','害羞'],['angry','生气'],['crying','大哭'],['confused','疑惑'],['veryHappy','很开心']]
const doc=ref({schemaVersion:1,characters:[],appearances:[],accessories:[],pages:[],products:[]}),version=ref('0'),published=ref(''),dirty=ref(false),loading=ref(false),busy=ref(false),error=ref(''),tab=ref('characters'),selected=ref(null),search=ref(''),assets=ref([]),history=ref([]),entities=ref([]),audits=ref([]),license=ref('')
const group=computed(()=>groups.find(g=>g.key===tab.value)),isContent=computed(()=>!!group.value),filtered=computed(()=>(doc.value[tab.value]||[]).filter(i=>(i.name||pageName(i.id)||'').includes(search.value)))
const savedSnapshot=ref(JSON.stringify(doc.value));
watch(doc,()=>{dirty.value=JSON.stringify(doc.value)!==savedSnapshot.value},{deep:true});
const roleName=id=>doc.value.characters.find(c=>c.id===id)?.name||id
async function task(fn){if(busy.value)return;busy.value=true;error.value='';try{return await fn()}catch(e){error.value=e.message;ElMessage.error(e.message)}finally{busy.value=false}}
async function refresh(){if(dirty.value){try{await ElMessageBox.confirm('刷新会丢弃未保存的编辑，是否继续？','刷新草稿')}catch{return}}loading.value=true;try{const r=await api('/content/draft');savedSnapshot.value=JSON.stringify(r.content);doc.value=r.content;version.value=r.version;published.value=r.publishedId;dirty.value=false;selected.value=null;assets.value=await api('/assets');history.value=await api('/content/releases');entities.value=(await api('/entities')).map(r=>({...r,saved:r.character_id}));if(can('content:audit'))audits.value=await api('/audit')}catch(e){error.value=e.message}finally{loading.value=false}}
function add(){const key=id();let item;if(tab.value==='characters'){const look=id();item={id:key,code:'IP_'+key.slice(0,6),name:'新角色',description:'角色介绍',defaultAppearanceId:look,backgroundAssetId:null,adoptionEnabled:true};doc.value.appearances.push({id:look,characterId:key,name:'默认造型',price:0,available:true,slots:Object.fromEntries(slots.map(([k])=>[k,'']))})}else if(tab.value==='appearances')item={id:key,characterId:doc.value.characters[0]?.id||'',name:'新造型',price:0,available:true,slots:Object.fromEntries(slots.map(([k])=>[k,'']))};else if(tab.value==='accessories')item={id:key,name:'新饰品',slot:'head',price:0,available:true,assetId:'',compatible:[]};else if(tab.value==='pages'){const p=Object.keys(pageNames).find(k=>!doc.value.pages.some(p=>p.id===k));if(!p)return ElMessage.info('所有页面均已配置');item={id:p,backgroundAssetId:null,banners:[]}}else item={id:key,name:'新商品',price:0,coverAssetId:'',detailAssetIds:[]};doc.value[tab.value].push(item);selected.value=item;dirty.value=true}
async function removeSelected(){try{await ElMessageBox.confirm('移除会在下一次发布时生效。','移除内容')}catch{return}doc.value[tab.value]=doc.value[tab.value].filter(i=>i.id!==selected.value.id);selected.value=null}
async function assetReferences(a){await task(async()=>{const r=await api('/assets/'+a.id+'/references');await ElMessageBox.alert('草稿引用：'+(r.draftReferenced?'是':'否')+'；历史发布引用：'+r.releaseIds.length+' 个版本。','素材引用')})}
async function removeAsset(a){try{await ElMessageBox.confirm('仅允许移除没有草稿、发布或有效预览引用的素材。','移除未引用素材')}catch{return}await task(async()=>{await api('/assets/'+a.id,{method:'DELETE'});assets.value=assets.value.filter(x=>x.id!==a.id);ElMessage.success('已移除，底层文件保留用于恢复')})}
async function save(){await task(async()=>{const r=await api('/content/draft',{method:'PUT',body:{expectedVersion:Number(version.value),content:doc.value}});version.value=r.version;savedSnapshot.value=JSON.stringify(doc.value);dirty.value=false;ElMessage.success('草稿已保存')})}
async function publish(){try{await ElMessageBox.confirm('将发布当前已保存草稿。宠物进度和已获得权益不会重置。','发布内容')}catch{return}await task(async()=>{await api('/content/validate',{method:'POST'});const key='ops-publish-'+version.value;let requestId=sessionStorage.getItem(key);if(!requestId){requestId=id();sessionStorage.setItem(key,requestId)}const r=await api('/content/publish',{method:'POST',body:{expectedVersion:Number(version.value),requestId}});sessionStorage.removeItem(key);version.value=r.version;published.value=r.releaseId;history.value=await api('/content/releases');ElMessage.success('发布成功')})}
async function rollback(row){try{await ElMessageBox.confirm('恢复这个内容版本，草稿和用户权益保持。','回滚内容')}catch{return}await task(async()=>{const r=await api('/content/rollback',{method:'POST',body:{expectedVersion:Number(version.value),requestId:id(),releaseId:row.id}});version.value=r.version;published.value=r.releaseId;history.value=await api('/content/releases');ElMessage.success('已回滚')})}
function fillSlots(){const normal=selected.value.slots.normal;if(!normal)return ElMessage.warning('请先选择正常图');for(const [k] of slots)if(!selected.value.slots[k])selected.value.slots[k]=normal;dirty.value=true}
async function upload(e){const file=e.target.files[0];if(!file)return;await task(async()=>{const form=new FormData();form.append('file',file);form.append('license',license.value);await api('/assets',{method:'POST',body:form});assets.value=await api('/assets');ElMessage.success('素材已上传，发布后才对用户可见')});e.target.value=''}
async function mapEntity(row){await task(async()=>{await api('/entities/'+row.id+'/character',{method:'PUT',body:{characterId:row.character_id}});row.saved=row.character_id;ElMessage.success('已关联')})}
async function moreAssets(){await task(async()=>assets.value.push(...await api('/assets?offset='+assets.value.length)))}
async function moreEntities(){await task(async()=>entities.value.push(...(await api('/entities?after='+(entities.value.at(-1)?.id||''))).map(r=>({...r,saved:r.character_id}))))}
async function moreHistory(){await task(async()=>history.value.push(...await api('/content/releases?before='+(history.value.at(-1)?.workspace_version||0))))}
async function moreAudit(){await task(async()=>audits.value.push(...await api('/audit?before='+(audits.value.at(-1)?.oper_id||0))))}
async function copy(value){try{await navigator.clipboard.writeText(value);ElMessage.success('已复制')}catch{ElMessage.error('浏览器不允许复制，请使用安全访问地址')}}
const previewOpen=ref(false),previewDoc=ref(null),previewToken=ref(''),previewLook=ref(''),previewExpression=ref('normal'),previewExtras=ref([])
const previewAppearance=computed(()=>previewDoc.value?.appearances.find(a=>a.id===previewLook.value))
const previewBackground=computed(()=>previewDoc.value?.characters.find(c=>c.id===previewAppearance.value?.characterId)?.backgroundAssetId||previewDoc.value?.pages.find(p=>p.id==='nestDefault')?.backgroundAssetId)
const compatibleExtras=computed(()=>previewDoc.value?.accessories.filter(a=>a.compatible.some(c=>c.appearanceId===previewLook.value))||[])
const selectedExtras=computed(()=>compatibleExtras.value.filter(a=>previewExtras.value.includes(a.id)))
function accessoryStyle(a){const f=a.compatible.find(c=>c.appearanceId===previewLook.value);return{left:f.x/10+'%',top:f.y/10+'%',width:f.width/10+'%',height:f.height/10+'%',zIndex:f.layer+20}}
async function preview(){await task(async()=>{const r=await api('/content/preview-tokens',{method:'POST'});previewToken.value=r.token;previewDoc.value=structuredClone(toRaw(doc.value));previewLook.value=previewDoc.value.appearances[0]?.id||'';previewExtras.value=[];previewOpen.value=true})}
async function inspectRelease(row){await task(async()=>{previewDoc.value=await api('/content/releases/'+row.id);previewToken.value='';previewLook.value=previewDoc.value.appearances[0]?.id||'';previewExtras.value=[];previewOpen.value=true})}
function beforeUnload(e){if(dirty.value){e.preventDefault();e.returnValue=''}}
onMounted(()=>{refresh();window.addEventListener('beforeunload',beforeUnload)})
onBeforeUnmount(()=>window.removeEventListener('beforeunload',beforeUnload))
